import{_ as e,o as i,c as l,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const b=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2023-11-08","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2023-11-08","date":"2023-11-08T00:00:00.000Z","updated":"2023-11-21T00:00:00.000Z","tags":["Ceph","分布式存储","librdkafka","librados","Ceph RGW"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_RGW_Refactoring_Meeting_2023-11-08.md","filePath":"posts/2023/Ceph_RGW_Refactoring_Meeting_2023-11-08.md","lastUpdated":1780460162000}'),r={name:"posts/2023/Ceph_RGW_Refactoring_Meeting_2023-11-08.md"};function o(n,a,h,d,s,c){return i(),l("div",null,[...a[0]||(a[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-ceph分布式存储系统中librdkafka库的问题讨论与解决方案" tabindex="-1">会议主题：Ceph分布式存储系统中librdkafka库的问题讨论与解决方案 <a class="header-anchor" href="#会议主题-ceph分布式存储系统中librdkafka库的问题讨论与解决方案" aria-label="Permalink to &quot;会议主题：Ceph分布式存储系统中librdkafka库的问题讨论与解决方案&quot;">​</a></h4><h4 id="参会人员-ceph研发团队成员" tabindex="-1">参会人员：Ceph研发团队成员 <a class="header-anchor" href="#参会人员-ceph研发团队成员" aria-label="Permalink to &quot;参会人员：Ceph研发团队成员&quot;">​</a></h4><h4 id="会议时间-2023年11月8日" tabindex="-1">会议时间：2023年11月8日 <a class="header-anchor" href="#会议时间-2023年11月8日" aria-label="Permalink to &quot;会议时间：2023年11月8日&quot;">​</a></h4><h4 id="会议地点-视频会议" tabindex="-1">会议地点：视频会议 <a class="header-anchor" href="#会议地点-视频会议" aria-label="Permalink to &quot;会议地点：视频会议&quot;">​</a></h4><h4 id="主要议题" tabindex="-1">主要议题： <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题：&quot;">​</a></h4><ol><li><p><strong>librdkafka库存在的问题</strong>：</p><ul><li>当前使用的librdkafka库版本较旧，存在崩溃和功能缺失问题。</li><li>崩溃问题已在新版本中修复，功能缺失包括无法以字符串形式传递证书颁发机构（CA）和客户端无法绕过服务器证书检查。</li></ul></li><li><p><strong>解决方案讨论</strong>：</p><ul><li>讨论了将librdkafka作为子模块引入Ceph项目的可行性。</li><li>决定采用静态链接方式解决动态链接问题，并确保子模块使用为临时解决方案。</li><li>计划向CentOS和Ubuntu提交bug报告，请求更新librdkafka版本。</li></ul></li><li><p><strong>后续行动计划</strong>：</p><ul><li>添加librdkafka作为子模块，并确保提交消息中包含子模块名称以获得批准。</li><li>向CentOS和Ubuntu提交bug报告，请求更新librdkafka版本。</li><li>监控子模块使用情况，评估是否需要长期保留。</li></ul></li></ol><h4 id="其他讨论" tabindex="-1">其他讨论： <a class="header-anchor" href="#其他讨论" aria-label="Permalink to &quot;其他讨论：&quot;">​</a></h4><ul><li><strong>Kraken的提问</strong>：讨论了在单个RADOS对象中存储所有主题（topics）的问题，以及数据模型改进的必要性和潜在的迁移成本。</li><li><strong>Ali的工作</strong>：讨论了配置管理和部署，计划在下次会议中进一步讨论。</li><li><strong>Kraken的另一个问题</strong>：关于使用Web Identity进行STS（Security Token Service）角色假设时遇到的问题，建议创建Tracker bug并寻求专家帮助。</li></ul><h4 id="会议总结" tabindex="-1">会议总结： <a class="header-anchor" href="#会议总结" aria-label="Permalink to &quot;会议总结：&quot;">​</a></h4><p>会议主要解决了Ceph项目中librdkafka库的版本问题和功能缺失，决定采用子模块方式并静态链接解决现有问题。同时，讨论了数据模型改进的必要性和潜在的迁移成本，并计划在后续工作中进一步处理。对于Web Identity的问题，建议创建Tracker bug并寻求专家帮助。</p><h4 id="后续行动" tabindex="-1">后续行动： <a class="header-anchor" href="#后续行动" aria-label="Permalink to &quot;后续行动：&quot;">​</a></h4><ul><li>实施librdkafka子模块的添加和静态链接。</li><li>提交bug报告，请求更新librdkafka版本。</li><li>监控子模块使用情况，评估长期保留的必要性。</li><li>创建Tracker bug，解决Web Identity问题。</li><li>讨论Standalone部署的编排问题和配置管理。</li></ul><h4 id="下次会议预告" tabindex="-1">下次会议预告： <a class="header-anchor" href="#下次会议预告" aria-label="Permalink to &quot;下次会议预告：&quot;">​</a></h4><ul><li>讨论Standalone部署的编排问题和配置管理。</li></ul><h4 id="会议结束" tabindex="-1">会议结束： <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束：&quot;">​</a></h4><p>感谢所有参会人员的积极参与和贡献，会议于[具体时间]结束。</p>',17)])])}const k=e(r,[["render",o]]);export{b as __pageData,k as default};
